31	@Data
32	@JsonPropertyOrder({ "receivedTotal", "processedSuccessfullyTotal", "systemExceptionsTotal", "userExceptionsTotal", "avgProcessLatency", "1min", "lastInvocation", "instances" })
33	public class FunctionStats {
34	
35	    /**
36	     * Overall total number of records function received from source
37	     **/
38	    public long receivedTotal;
39	
40	    /**
41	     * Overall total number of records successfully processed by user function
42	     **/
43	    public long processedSuccessfullyTotal;
44	
45	    /**
46	     * Overall total number of system exceptions thrown
47	     **/
48	    public long systemExceptionsTotal;
49	
50	    /**
51	     * Overall total number of user exceptions thrown
52	     **/
53	    public long userExceptionsTotal;
54	
55	    /**
56	     * Average process latency for function
57	     **/
58	    public double avgProcessLatency;
59	
60	    @JsonProperty("1min")
61	    public FunctionInstanceStats.FunctionInstanceStatsDataBase oneMin = new FunctionInstanceStats.FunctionInstanceStatsDataBase();
62	
63	    /**
64	     * Timestamp of when the function was last invoked by any instance
65	     **/
66	    public long lastInvocation;
67	
68	    @Data
69	    @JsonPropertyOrder({ "instanceId", "metrics" })
70	    public static class FunctionInstanceStats {
71	
72	        /** Instance Id of function instance **/
73	        public int instanceId;
74	
75	        @Data
76	        @JsonPropertyOrder({ "receivedTotal", "processedSuccessfullyTotal", "systemExceptionsTotal", "userExceptionsTotal", "avgProcessLatency" })
77	        public static class FunctionInstanceStatsDataBase {
78	            /**
79	             * Total number of records function received from source for instance
80	             **/
81	            public long receivedTotal;
82	
83	            /**
84	             * Total number of records successfully processed by user function for instance
85	             **/
86	            public long processedSuccessfullyTotal;
87	
88	            /**
89	             * Total number of system exceptions thrown for instance
90	             **/
91	            public long systemExceptionsTotal;
92	
93	            /**
94	             * Total number of user exceptions thrown for instance
95	             **/
96	            public long userExceptionsTotal;
97	
98	            /**
99	             * Average process latency for function for instance
100	             **/
101	            public double avgProcessLatency;
102	        }
103	
104	        @Data
105	        @JsonPropertyOrder({ "receivedTotal", "processedSuccessfullyTotal", "systemExceptionsTotal", "userExceptionsTotal", "avgProcessLatency", "1min", "lastInvocation", "userMetrics" })
106	        public static class FunctionInstanceStatsData extends FunctionInstanceStatsDataBase {
107	
108	            @JsonProperty("1min")
109	            public FunctionInstanceStatsDataBase oneMin = new FunctionInstanceStatsDataBase();
110	
111	            /**
112	             * Timestamp of when the function was last invoked for instance
113	             **/
114	            public long lastInvocation;
115	
116	            /**
117	             * Map of user defined metrics
118	             **/
119	            public Map<String, Double> userMetrics = new HashMap<>();
120	        }
121	
122	        public FunctionInstanceStatsData metrics = new FunctionInstanceStatsData();
123	    }
124	
125	    public List<FunctionInstanceStats> instances = new LinkedList<>();
126	
127	    public void addInstance(FunctionInstanceStats functionInstanceStats) {
128	        instances.add(functionInstanceStats);
129	    }
130	
131	    public FunctionStats calculateOverall() {
132	
133	        lastInvocation = 0;
134	        instances.forEach(new Consumer<FunctionInstanceStats>() {
135	            @Override
136	            public void accept(FunctionInstanceStats functionInstanceStats) {
137	                FunctionInstanceStats.FunctionInstanceStatsData functionInstanceStatsData = functionInstanceStats.getMetrics();
138	                receivedTotal += functionInstanceStatsData.receivedTotal;
139	                processedSuccessfullyTotal += functionInstanceStatsData.processedSuccessfullyTotal;
140	                systemExceptionsTotal += functionInstanceStatsData.systemExceptionsTotal;
141	                userExceptionsTotal += functionInstanceStatsData.userExceptionsTotal;
142	                avgProcessLatency += functionInstanceStatsData.avgProcessLatency;
143	
144	                oneMin.receivedTotal += functionInstanceStatsData.oneMin.receivedTotal;
145	                oneMin.processedSuccessfullyTotal += functionInstanceStatsData.oneMin.processedSuccessfullyTotal;
146	                oneMin.systemExceptionsTotal += functionInstanceStatsData.oneMin.systemExceptionsTotal;
147	                oneMin.userExceptionsTotal += functionInstanceStatsData.oneMin.userExceptionsTotal;
148	                oneMin.avgProcessLatency += functionInstanceStatsData.oneMin.avgProcessLatency;
149	
150	                if (functionInstanceStatsData.lastInvocation > lastInvocation) {
151	                    lastInvocation = functionInstanceStatsData.lastInvocation;
152	                }
153	
154	            }
155	        });
156	        // calculate average from sum
157	        avgProcessLatency = avgProcessLatency / instances.size();
158	
159	        // calculate 1min average from sum
160	        oneMin.avgProcessLatency = oneMin.avgProcessLatency / instances.size();
161	
162	        return this;
163	    }
164	}
